package main

import \(
	"encoding/json"
	"fmt"
	"io"
	"math"
	"net/http"
	"strconv"
	"strings"
	"time"
\)

type filmixPostRoot struct {
	PlayerLinks *filmixPlayerLinks `json:"player_links"`
	Quality     string             `json:"quality"`
}

type filmixPlayerLinks struct {
	Movie    []filmixMovie                     `json:"movie"`
	Playlist map[string]map[string]json.RawMessage `json:"playlist"`
}

type filmixMovie struct {
	Link        string         `json:"link"`
	Translation string         `json:"translation"`
	Qualities   filmixIntSlice `json:"qualities"`
}

type filmixInt int

func \(n *filmixInt\) UnmarshalJSON\(data []byte\) error {
	raw := strings.TrimSpace\(string\(data\)\)
	if raw == "" || raw == "null" {
		*n = 0
		return nil
	}
	if strings.HasPrefix\(raw, `"`\) && strings.HasSuffix\(raw, `"`\) {
		raw = strings.Trim\(raw, `"`\)
		if v, err := strconv.Atoi\(strings.TrimSpace\(raw\)\); err == nil {
			*n = filmixInt\(v\)
			return nil
		}
		*n = 0
		return nil
	}
	var num json.Number
	if err := json.Unmarshal\(data, &num\); err == nil {
		if i64, err := num.Int64\(\); err == nil {
			*n = filmixInt\(i64\)
			return nil
		}
		if f64, err := num.Float64\(\); err == nil {
			*n = filmixInt\(int\(math.Round\(f64\)\)\)
			return nil
		}
	}
	*n = 0
	return nil
}

type filmixIntSlice []int

func \(s *filmixIntSlice\) UnmarshalJSON\(data []byte\) error {
	trimmed := strings.TrimSpace\(string\(data\)\)
	if trimmed == "" || trimmed == "null" {
		*s = nil
		return nil
	}
	var anyItems []any
	if err := json.Unmarshal\(data, &anyItems\); err != nil {
		*s = nil
		return nil
	}
	out := make\([]int, 0, len\(anyItems\)\)
	for _, item := range anyItems {
		switch t := item.\(type\) {
		case float64:
			out = append\(out, int\(t\)\)
		case string:
			if n, err := strconv.Atoi\(strings.TrimSpace\(t\)\); err == nil {
				out = append\(out, n\)
			}
		}
	}
	*s = out
	return nil
}

func main\(\) {
	client := &http.Client{Timeout: 15 * time.Second}
	resp, err := client.Get\("http://filmixapp.cyou/api/v2/post/81482?user_dev_apk=2.0.1&user_dev_id=&user_dev_name=Xiaomi&user_dev_os=11&user_dev_token=&user_dev_vendor=Xiaomi"\)
	if err != nil {
		fmt.Printf\("HTTP error: %v\\n", err\)
		return
	}
	defer resp.Body.Close\(\)
	fmt.Printf\("HTTP status: %d\\n", resp.StatusCode\)

	body, err := io.ReadAll\(resp.Body\)
	if err != nil {
		fmt.Printf\("Read error: %v\\n", err\)
		return
	}
	fmt.Printf\("Body length: %d\\n", len\(body\)\)

	// Apply jsonFix
	jsonFix := strings.ReplaceAll\(string\(body\), `"playlist":[],`, `"playlist":null,`\)
	jsonFix = strings.ReplaceAll\(jsonFix, `"playlist":[]}`, `"playlist":null}`\)

	var root filmixPostRoot
	if err := json.Unmarshal\([]byte\(jsonFix\), &root\); err != nil {
		fmt.Printf\("Unmarshal error: %v\\n", err\)
		return
	}

	fmt.Printf\("PlayerLinks is nil: %v\\n", root.PlayerLinks == nil\)
	if root.PlayerLinks != nil {
		fmt.Printf\("Movie count: %d\\n", len\(root.PlayerLinks.Movie\)\)
		fmt.Printf\("Playlist count: %d\\n", len\(root.PlayerLinks.Playlist\)\)
		for i, m := range root.PlayerLinks.Movie {
			fmt.Printf\("  Movie[%d]: link=%s... translation=%s qualities=%v\\n", i, m.Link[:60], m.Translation, m.Qualities\)
		}
	}
	fmt.Printf\("Quality: %s\\n", root.Quality\)
}
GOEOF)
